// The shared golden cases in `fixtures/timeline`, generated by the web client:
// this port must turn the same snapshot and events into the same timeline.
// Mirrors `TimelineFixturesTest.kt` and `apps/web/src/lib/timeline-fixtures.test.ts`.
import 'dart:convert';
import 'dart:io';

import 'package:pirc_client/pirc_client.dart';
import 'package:test/test.dart';

final _dir = Directory('../../fixtures/timeline');
int _clock() => 1000000000;

Map<String, Object?> _load(String name) =>
    jsonDecode(File('${_dir.path}/$name').readAsStringSync())
        as Map<String, Object?>;

/// Drop absent (null) and `false` values, as the web projection does.
Map<String, Object?> _defined(Map<String, Object?> entries) => {
  for (final MapEntry(:key, :value) in entries.entries)
    if (value != null && value != false) key: value,
};

int? _count(int size) => size > 0 ? size : null;

Map<String, Object?> _tool(ToolCall item) => _defined({
  'id': item.id,
  'name': item.name,
  'status': item.status,
  'input': item.input,
  'output': item.output,
  'diff': item.diff,
  'images': _count(item.images.length),
  'operations': item.operations.isEmpty
      ? null
      : item.operations.map(_tool).toList(),
});

Map<String, Object?> _message(Message message) => _defined({
  'id': message.id,
  'role': message.role,
  'content': message.content,
  'isPartial': message.isPartial,
  'thinking': message.thinking,
  'thinkingRedacted': message.thinkingRedacted,
  'stopReason': message.stopReason,
  'errorMessage': message.errorMessage,
  'model': message.model,
  'systemKind': message.systemKind,
  'level': message.level,
  'label': message.label,
  'meta': message.meta,
  'images': _count(message.images.length),
  'tools': message.tools.isEmpty ? null : message.tools.map(_tool).toList(),
});

/// Mirrors `project` in `apps/web/src/lib/timeline-fixtures.test.ts`.
Map<String, Object?> project(SessionState state) => {
  'cursor': state.cursor,
  'runnerEpoch': state.runnerEpoch,
  'needsSnapshot': state.needsSnapshot,
  'sessionName': state.session.name,
  'pinned': state.session.pinned,
  'runStatus': state.run?.status,
  'runnerStatus': state.runnerStatus,
  'selectedModelId': state.selectedModelId,
  'thinkingLevel': state.thinkingLevel,
  'queue': [for (final item in state.queue) '${item.kind}:${item.content}'],
  'widgets': state.widgets,
  'statuses': state.statuses,
  'interactions': [
    for (final item in state.interactions)
      _defined({
        'id': item.id,
        'kind': item.kind,
        'toolCallId': item.toolCallId,
        'title': item.title,
        'description': item.description,
        'status': item.status,
        'multiple': item.kind == 'select' && item.multiple,
        'options': item.kind == 'select'
            ? [
                for (final option in item.options)
                  _defined({
                    'value': option.value,
                    'description': option.description,
                  }),
              ]
            : null,
      }),
  ],
  'messages': state.messages.map(_message).toList(),
};

void main() {
  final files =
      _dir
          .listSync()
          .whereType<File>()
          .where((file) => file.path.endsWith('.json'))
          .map((file) => file.uri.pathSegments.last)
          .toList()
        ..sort();

  test('fixtures exist', () => expect(files, isNotEmpty));

  for (final name in files) {
    test('$name matches the web client', () {
      final fixture = _load(name);
      final expected = fixture['expected'] as Map<String, Object?>;
      var state = snapshotState(fixture['snapshot'], now: _clock);
      expect(
        project(state),
        equals(expected['afterSnapshot']),
        reason: '$name: after the snapshot',
      );
      for (final raw in fixture['events'] as List) {
        state = reduceEvent(
          state,
          normalizeEvent(raw, now: _clock),
          now: _clock,
        );
      }
      expect(
        project(state),
        equals(expected['afterEvents']),
        reason: '$name: after the events',
      );
    });
  }

  test('session_deleted is explicit and never requests another snapshot', () {
    final state = snapshotState(
      _load('streaming-turn.json')['snapshot'],
      now: _clock,
    );
    final envelope = normalizeEvent({
      'sessionId': state.session.id,
      'epoch': state.runnerEpoch,
      'sequence': 99,
      'type': 'session_deleted',
      'data': {'sessionId': state.session.id},
    }, now: _clock);
    expect(envelope.event, isA<SessionDeleted>());

    // Deletion is terminal even if the runner epoch changed before it arrived.
    final reduced = reduceEvent(
      state,
      envelope.copyWith(runnerEpoch: 'different-epoch'),
      now: _clock,
    );
    expect(reduced.needsSnapshot, isFalse);
    expect(reduced.cursor, envelope.cursor);
    expect(reduced.messages, same(state.messages));
  });

  test('only the reserved pots custom type carries trusted provenance', () {
    const content = '<b>literal instruction</b>';
    Map<String, Object?> raw(String role, String type) => {
      'role': role,
      'customType': type,
      'content': content,
      'details': {'actor': 'pots'},
    };
    final trusted = piMessage(raw('custom', 'pots-dispatch'), now: _clock)!;
    expect(trusted.role, 'system');
    expect(trusted.systemKind, 'pots');
    expect(trusted.label, 'From pots');
    expect(trusted.content, content);
    for (final role in ['user', 'assistant', 'custom']) {
      final ordinary = piMessage(raw(role, 'ordinary-extension'), now: _clock)!;
      expect(ordinary.systemKind, isNot('pots'));
      expect(ordinary.label, isNot('From pots'));
    }
  });
}
